DROP TABLE IF EXISTS `property_assessment_history`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `property_assessment_history` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `property_id` int(11) NOT NULL,
  `td_number` varchar(100) DEFAULT NULL,
  `assessed_value` decimal(14,2) DEFAULT NULL,
  `tax_year` varchar(100) DEFAULT NULL,
  `kind_of_property` varchar(100) DEFAULT NULL,
  `changed_by` varchar(255) DEFAULT NULL,
  `change_reason` varchar(255) DEFAULT 'Import Update',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_assessment_history_property_id` (`property_id`),
  CONSTRAINT `fk_assessment_history_property` FOREIGN KEY (`property_id`) REFERENCES `properties` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

